d=[shot(p[0],3,'固定正面中景，董白在画面中央，刀柄在左上，刀身斜贯右下，刀鞘在右侧近层，脸与刀路分开。','董白把长刀从鞘口顺势抽开，细长刀身沿左上至右下显露。她低头闭眼，像把杂念收住，双马尾随抽刀扬起再落缓；刀与鞘完全分开后，双手保持稳。','深褐岩壁退在后层，浅白雾气在腰侧和下方翻起，边缘缓慢散薄。','无台词。','左上柔光保持，刀刃留窄而清楚的冷白高光，雾气稍亮，黑色衣装轮廓分离。','连续清脆出鞘声，细电流底响，雾气散开时一声柔短气流。'),shot(p[1],8,'固定三分之二侧身中全景，董白在画面中央偏右，面朝左上，近手与鞘向左下伸，刀在肩后斜向左上。','董白抬眼看向左上方，侧过身把刀留在肩后。她轻轻打发刚才的问题，接着从容说出威胁，眼神比语气更冷；近手握鞘一直垂在左下，双马尾随侧身轻摆后收住。','后方深褐岩壁可见凸石与裂缝，左侧浅白雾气缓缓散薄，人物前后层次清楚。','董白说：“まあ、どうでもいいや。たっぷり遊んでから、殺してあげる。”（先随意，后句轻松却明确，带冷静的威胁感。）',LIGHT,'洞窟底声、衣摆轻擦，刀上电流细响保持低位。',speech=7.3)]
write('drafts',7,d)
